//! Module manifest, schema 3 (docs/module-architecture.md 4.3, exact layouts in docs/module-contract.md): data generated by `hyperion_module!` at build time and embedded in every module image behind the
//! export `hyperion_manifest`. The host reads it BEFORE `hyperion_set_host` and before any module code runs, and verifies every `-api` dependency (hash, provider, data marker) against the host's tables and the generation's other modules
//! (`hyperion-gen` gate, the same code in `activate`). A mismatch rejects the build
//! with a message naming the component and both layouts; the running module stays.
//!
//! The Rust-only `hyperion_manifest` export is separate from `Info` (the Zig-shared table) so `Info` stays unchanged. Everything here is plain
//! `repr(C)` data and `'static` pointers into the image's `.rodata`; the recipes are the same `Layout::RECIPE` trees the layout hash is made of
//! (host and module share one rustc, enforced by `BUILD_ID`, so the host may read them directly).
use hyperion_layout::layout::Recipe;
use core::ffi::c_char;

/// "HYPEMAN1".
pub const MANIFEST_MAGIC: u64 = 0x314E_414D_4550_5948;
/// Bump on any change to the structs below.
pub const MANIFEST_SCHEMA: u32 = 3;

/// The module's Cargo dependency on this `-api` crate is REQUIRED (`[package.metadata.hyperion] required = [..]`): without a provider (a module that
/// provides the crate, or the host for `hyperion-api`/`hyperion-kernel-api`) the module is not loaded. Default is optional: a provider that is
/// absent is fine, a provider built against another layout hash is not.
pub const DEP_REQUIRED: u32 = 1;
/// The module PROVIDES this api crate: it registers its components and publishes its services.
pub const DEP_PROVIDES: u32 = 2;
/// The module needs this data file (its marker must equal the stamp of the file in the generation's assets). Default for every row.
pub const DATA_REQUIRED: u32 = 1;

/// One Cargo dependency of the module on an `-api` crate, generated from `Cargo.toml` by `hyperion-module-build` (never hand-written).
/// Rust-only data (the same rustc builds host and modules): `layouts` points at the image's own copy of the crate's `API_LAYOUTS`. The component
/// and service rows of the dependency are `layouts.types` (role: provider when `DEP_PROVIDES`, else consumer); there is no separate row list.
#[repr(C)]
pub struct ManifestDep {
    pub flags: u32,
    pub _pad: u32,
    pub layouts: &'static hyperion_api_layouts::ApiLayouts,
}

/// A data file this image reads (`data_schema!`): the marker of the reader's format. Generated from the dependency's `API_LAYOUTS.data`.
#[repr(C)]
pub struct ManifestData {
    /// `"view.rigs"`, NUL terminated.
    pub name: *const c_char,
    pub marker: u64,
    pub flags: u32,
    pub _pad: u32,
}

/// A module-private component (`<module>.*`), provided by this image only ([`local`]).
#[repr(C)]
pub struct ManifestComp {
    pub name: *const c_char,
    pub size: u32,
    pub align: u32,
    pub hash: u64,
    /// The layout tree (for the mismatch message).
    pub recipe: *const Recipe,
}
unsafe impl Sync for ManifestComp {}
unsafe impl Sync for ManifestData {}

/// Schema 3 (docs/module-contract.md has the offsets). Size 88.
#[repr(C)]
pub struct Manifest {
    pub magic: u64,
    pub schema: u32,
    /// `size_of::<Manifest>()`: lets a newer host read an older prefix.
    pub size: u32,
    pub name: *const c_char,
    pub version: u32,
    /// `hyperion_abi::ABI_VERSION` the module was built against.
    pub contract: u32,
    /// Length in bytes of the `HostApi` table the image calls into.
    pub host_need: u32,
    pub _pad: u32,
    pub build_id: u64,
    pub n_deps: u32,
    pub n_data: u32,
    /// The module's `-api` crate dependencies, generated from its Cargo.toml.
    pub deps: *const ManifestDep,
    pub data: *const ManifestData,
    pub n_local: u32,
    pub _pad2: u32,
    pub local: *const ManifestComp,
}
unsafe impl Sync for Manifest {}
unsafe impl Sync for ManifestDep {}

const _: () = {
    assert!(size_of::<Manifest>() == 88);
    assert!(size_of::<ManifestDep>() == 16);
    assert!(size_of::<ManifestData>() == 24);
    assert!(size_of::<ManifestComp>() == 32);
};

pub type ManifestFn = unsafe extern "C" fn() -> *const Manifest;

/// One line per field, e.g. `{ x: f32 @0, y: f32 @4 } size 8 align 4`: what the mismatch message prints for the module's side.
pub fn describe(r: &Recipe) -> String {
    fn ty(r: &Recipe) -> String {
        match r {
            Recipe::Prim { name, .. } => (*name).to_string(),
            Recipe::Array { len, elem, .. } => format!("[{}; {len}]", ty(elem)),
            Recipe::Struct { fields, .. } => {
                let f: Vec<String> = fields.iter().map(|f| format!("{}: {} @{}", f.name, ty(f.ty), f.offset)).collect();
                format!("{{ {} }}", f.join(", "))
            }
            Recipe::Enum { tag, consts, .. } => format!("enum({}; {} consts)", ty(tag), consts.len()),
            Recipe::Opaque { shape, .. } => ty(shape),
        }
    }
    format!("{} size {} align {}", ty(r), r.size(), r.align())
}

/// Same as [`describe`] but only the top-level member list, without nesting (used for the compact first line).
pub fn members(r: &Recipe) -> Vec<(String, usize, usize)> {
    match r {
        Recipe::Struct { fields, .. } => fields.iter().map(|f| (f.name.to_string(), f.offset, f.ty.size())).collect(),
        _ => vec![],
    }
}

/// Build the `ManifestComp` row of a module-private component under its world name (`LocalComponent::NAME`, NUL terminated by the caller's
/// `concat!(.., "\0")`; `hyperion_module!` does it).
pub const fn local<T: hyperion_api_layouts::LocalComponent>(name_nul: &'static str) -> ManifestComp {
    ManifestComp { name: name_nul.as_ptr() as *const c_char, size: size_of::<T>() as u32, align: align_of::<T>() as u32, hash: T::HASH, recipe: T::RECIPE as *const Recipe }
}
